class CalledProcessError(SubprocessError):
    """Raised when run() is called with check=True and the process
    returns a non-zero exit status.

    Attributes:
      cmd, returncode, stdout, stderr, output
    """

    def __init__(self, returncode, cmd, output=None, stderr=None):
        self.returncode = returncode
        self.cmd = cmd
        self.output = output
        self.stderr = stderr

    def __str__(self):
        if self.returncode and self.returncode < 0:
            try:
                return "Command '%s' died with %r." % (self.cmd, signal.Signals(-self.returncode))
            except ValueError:
                return "Command '%s' died with unknown signal %d." % (self.cmd, -self.returncode)
        else:
            return "Command '%s' returned non-zero exit status %d." % (self.cmd, self.returncode)

    @property
    def stdout(self):
        """Alias for output attribute, to match stderr"""
        return self.output

    @stdout.setter
    def stdout(self, value):
        self.output = value

class TimeoutExpired(SubprocessError):
    """This exception is raised when the timeout expires while waiting for a
    child process.

    Attributes:
        cmd, output, stdout, stderr, timeout
    """

    def __init__(self, cmd, timeout, output=None, stderr=None):
        self.cmd = cmd
        self.timeout = timeout
        self.output = output
        self.stderr = stderr

    def __str__(self):
        return "Command '%s' timed out after %s seconds" % (self.cmd, self.timeout)

    @property
    def stdout(self):
        return self.output

    @stdout.setter
    def stdout(self, value):
        self.output = value

def _args_from_interpreter_flags():
    """Return a list of command-line arguments reproducing the current
    settings in sys.flags, sys.warnoptions and sys._xoptions."""
    flag_opt_map = {'debug': 'd', 'dont_write_bytecode': 'B', 'no_site': 'S', 'verbose': 'v', 'bytes_warning': 'b', 'quiet': 'q'}
    args = _optim_args_from_interpreter_flags()
    for (flag, opt) in flag_opt_map.items():
        v = getattr(sys.flags, flag)
        if v > 0:
            args.append('-' + opt * v)
    if sys.flags.isolated:
        args.append('-I')
    else:
        if sys.flags.ignore_environment:
            args.append('-E')
        if sys.flags.no_user_site:
            args.append('-s')
        if sys.flags.safe_path:
            args.append('-P')
    warnopts = sys.warnoptions[:]
    xoptions = getattr(sys, '_xoptions', {})
    bytes_warning = sys.flags.bytes_warning
    dev_mode = sys.flags.dev_mode
    if bytes_warning > 1:
        warnopts.remove('error::BytesWarning')
    elif bytes_warning:
        warnopts.remove('default::BytesWarning')
    if dev_mode:
        warnopts.remove('default')
    for opt in warnopts:
        args.append('-W' + opt)
    if dev_mode:
        args.extend(('-X', 'dev'))
    for opt in ('faulthandler', 'tracemalloc', 'importtime', 'frozen_modules', 'showrefcount', 'utf8'):
        if opt in xoptions:
            value = xoptions[opt]
            if value is True:
                arg = opt
            else:
                arg = '%s=%s' % (opt, value)
            args.extend(('-X', arg))
    return args

def call(*popenargs, timeout=None, **kwargs):
    """Run command with arguments.  Wait for command to complete or
    timeout, then return the returncode attribute.

    The arguments are the same as for the Popen constructor.  Example:

    retcode = call(["ls", "-l"])
    """
    with Popen(*popenargs, **kwargs) as p:
        try:
            return p.wait(timeout=timeout)
        except:
            p.kill()
            raise

class CompletedProcess(object):
    """A process that has finished running.

    This is returned by run().

    Attributes:
      args: The list or str args passed to run().
      returncode: The exit code of the process, negative for signals.
      stdout: The standard output (None if not captured).
      stderr: The standard error (None if not captured).
    """

    def __init__(self, args, returncode, stdout=None, stderr=None):
        self.args = args
        self.returncode = returncode
        self.stdout = stdout
        self.stderr = stderr

    def __repr__(self):
        args = ['args={!r}'.format(self.args), 'returncode={!r}'.format(self.returncode)]
        if self.stdout is not None:
            args.append('stdout={!r}'.format(self.stdout))
        if self.stderr is not None:
            args.append('stderr={!r}'.format(self.stderr))
        return '{}({})'.format(type(self).__name__, ', '.join(args))
    __class_getitem__ = classmethod(types.GenericAlias)

    def check_returncode(self):
        """Raise CalledProcessError if the exit code is non-zero."""
        if self.returncode:
            raise CalledProcessError(self.returncode, self.args, self.stdout, self.stderr)

@property
def stdout(self):
    """Alias for output attribute, to match stderr"""
    return self.output

def check_returncode(self):
    """Raise CalledProcessError if the exit code is non-zero."""
    if self.returncode:
        raise CalledProcessError(self.returncode, self.args, self.stdout, self.stderr)

def __init__(self, args, bufsize=-1, executable=None, stdin=None, stdout=None, stderr=None, preexec_fn=None, close_fds=True, shell=False, cwd=None, env=None, universal_newlines=None, startupinfo=None, creationflags=0, restore_signals=True, start_new_session=False, pass_fds=(), *, user=None, group=None, extra_groups=None, encoding=None, errors=None, text=None, umask=-1, pipesize=-1, process_group=None):
    """Create new Popen instance."""
    if not _can_fork_exec:
        raise OSError(errno.ENOTSUP, f'{sys.platform} does not support processes.')
    _cleanup()
    self._waitpid_lock = threading.Lock()
    self._input = None
    self._communication_started = False
    if bufsize is None:
        bufsize = -1
    if not isinstance(bufsize, int):
        raise TypeError('bufsize must be an integer')
    if pipesize is None:
        pipesize = -1
    if not isinstance(pipesize, int):
        raise TypeError('pipesize must be an integer')
    if _mswindows:
        if preexec_fn is not None:
            raise ValueError('preexec_fn is not supported on Windows platforms')
    else:
        if pass_fds and (not close_fds):
            warnings.warn('pass_fds overriding close_fds.', RuntimeWarning)
            close_fds = True
        if startupinfo is not None:
            raise ValueError('startupinfo is only supported on Windows platforms')
        if creationflags != 0:
            raise ValueError('creationflags is only supported on Windows platforms')
    self.args = args
    self.stdin = None
    self.stdout = None
    self.stderr = None
    self.pid = None
    self.returncode = None
    self.encoding = encoding
    self.errors = errors
    self.pipesize = pipesize
    if text is not None and universal_newlines is not None and (bool(universal_newlines) != bool(text)):
        raise SubprocessError('Cannot disambiguate when both text and universal_newlines are supplied but different. Pass one or the other.')
    self.text_mode = encoding or errors or text or universal_newlines
    if self.text_mode and encoding is None:
        self.encoding = encoding = _text_encoding()
    self._sigint_wait_secs = 0.25
    self._closed_child_pipe_fds = False
    if self.text_mode:
        if bufsize == 1:
            line_buffering = True
            bufsize = -1
        else:
            line_buffering = False
    if process_group is None:
        process_group = -1
    gid = None
    if group is not None:
        if not hasattr(os, 'setregid'):
            raise ValueError("The 'group' parameter is not supported on the current platform")
        elif isinstance(group, str):
            try:
                import grp
            except ImportError:
                raise ValueError('The group parameter cannot be a string on systems without the grp module')
            gid = grp.getgrnam(group).gr_gid
        elif isinstance(group, int):
            gid = group
        else:
            raise TypeError('Group must be a string or an integer, not {}'.format(type(group)))
        if gid < 0:
            raise ValueError(f'Group ID cannot be negative, got {gid}')
    gids = None
    if extra_groups is not None:
        if not hasattr(os, 'setgroups'):
            raise ValueError("The 'extra_groups' parameter is not supported on the current platform")
        elif isinstance(extra_groups, str):
            raise ValueError('Groups must be a list, not a string')
        gids = []
        for extra_group in extra_groups:
            if isinstance(extra_group, str):
                try:
                    import grp
                except ImportError:
                    raise ValueError('Items in extra_groups cannot be strings on systems without the grp module')
                gids.append(grp.getgrnam(extra_group).gr_gid)
            elif isinstance(extra_group, int):
                gids.append(extra_group)
            else:
                raise TypeError('Items in extra_groups must be a string or integer, not {}'.format(type(extra_group)))

def communicate(self, input=None, timeout=None):
    """Interact with process: Send data to stdin and close it.
        Read data from stdout and stderr, until end-of-file is
        reached.  Wait for process to terminate.

        The optional "input" argument should be data to be sent to the
        child process, or None, if no data should be sent to the child.
        communicate() returns a tuple (stdout, stderr).

        By default, all communication is in bytes, and therefore any
        "input" should be bytes, and the (stdout, stderr) will be bytes.
        If in text mode (indicated by self.text_mode), any "input" should
        be a string, and (stdout, stderr) will be strings decoded
        according to locale encoding, or by "encoding" if set. Text mode
        is triggered by setting any of text, encoding, errors or
        universal_newlines.
        """
    if self._communication_started and input:
        raise ValueError('Cannot send input after starting communication')
    if timeout is None and (not self._communication_started) and ([self.stdin, self.stdout, self.stderr].count(None) >= 2):
        stdout = None
        stderr = None
        if self.stdin:
            self._stdin_write(input)
        elif self.stdout:
            stdout = self.stdout.read()
            self.stdout.close()
        elif self.stderr:
            stderr = self.stderr.read()
            self.stderr.close()
        self.wait()
    else:
        if timeout is not None:
            endtime = _time() + timeout
        else:
            endtime = None
        try:
            (stdout, stderr) = self._communicate(input, endtime, timeout)
        except KeyboardInterrupt:
            if timeout is not None:
                sigint_timeout = min(self._sigint_wait_secs, self._remaining_time(endtime))
            else:
                sigint_timeout = self._sigint_wait_secs
            self._sigint_wait_secs = 0
            try:
                self._wait(timeout=sigint_timeout)
            except TimeoutExpired:
                pass
            raise
        finally:
            self._communication_started = True
        sts = self.wait(timeout=self._remaining_time(endtime))
    return (stdout, stderr)

def poll(self):
    """Check if child process has terminated. Set and return returncode
        attribute."""
    return self._internal_poll()

def _remaining_time(self, endtime):
    """Convenience for _communicate when computing timeouts."""
    if endtime is None:
        return None
    else:
        return endtime - _time()

def _check_timeout(self, endtime, orig_timeout, stdout_seq, stderr_seq, skip_check_and_raise=False):
    """Convenience for checking if a timeout has expired."""
    if endtime is None:
        return
    if skip_check_and_raise or _time() > endtime:
        raise TimeoutExpired(self.args, orig_timeout, output=b''.join(stdout_seq) if stdout_seq else None, stderr=b''.join(stderr_seq) if stderr_seq else None)

def wait(self, timeout=None):
    """Wait for child process to terminate; returns self.returncode."""
    if timeout is not None:
        endtime = _time() + timeout
    try:
        return self._wait(timeout=timeout)
    except KeyboardInterrupt:
        if timeout is not None:
            sigint_timeout = min(self._sigint_wait_secs, self._remaining_time(endtime))
        else:
            sigint_timeout = self._sigint_wait_secs
        self._sigint_wait_secs = 0
        try:
            self._wait(timeout=sigint_timeout)
        except TimeoutExpired:
            pass
        raise

@contextlib.contextmanager
def _on_error_fd_closer(self):
    """Helper to ensure file descriptors opened in _get_handles are closed"""
    to_close = []
    try:
        yield to_close
    except:
        if hasattr(self, '_devnull'):
            to_close.append(self._devnull)
            del self._devnull
        for fd in to_close:
            try:
                if _mswindows and isinstance(fd, Handle):
                    fd.Close()
                else:
                    os.close(fd)
            except OSError:
                pass
        raise

def _get_handles(self, stdin, stdout, stderr):
    """Construct and return tuple with IO objects:
            p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite
            """
    if stdin is None and stdout is None and (stderr is None):
        return (-1, -1, -1, -1, -1, -1)
    (p2cread, p2cwrite) = (-1, -1)
    (c2pread, c2pwrite) = (-1, -1)
    (errread, errwrite) = (-1, -1)
    with self._on_error_fd_closer() as err_close_fds:
        if stdin is None:
            p2cread = _winapi.GetStdHandle(_winapi.STD_INPUT_HANDLE)
            if p2cread is None:
                (p2cread, _) = _winapi.CreatePipe(None, 0)
                p2cread = Handle(p2cread)
                err_close_fds.append(p2cread)
                _winapi.CloseHandle(_)
        elif stdin == PIPE:
            (p2cread, p2cwrite) = _winapi.CreatePipe(None, 0)
            (p2cread, p2cwrite) = (Handle(p2cread), Handle(p2cwrite))
            err_close_fds.extend((p2cread, p2cwrite))
        elif stdin == DEVNULL:
            p2cread = msvcrt.get_osfhandle(self._get_devnull())
        elif isinstance(stdin, int):
            p2cread = msvcrt.get_osfhandle(stdin)
        else:
            p2cread = msvcrt.get_osfhandle(stdin.fileno())
        p2cread = self._make_inheritable(p2cread)
        if stdout is None:
            c2pwrite = _winapi.GetStdHandle(_winapi.STD_OUTPUT_HANDLE)
            if c2pwrite is None:
                (_, c2pwrite) = _winapi.CreatePipe(None, 0)
                c2pwrite = Handle(c2pwrite)
                err_close_fds.append(c2pwrite)
                _winapi.CloseHandle(_)
        elif stdout == PIPE:
            (c2pread, c2pwrite) = _winapi.CreatePipe(None, 0)
            (c2pread, c2pwrite) = (Handle(c2pread), Handle(c2pwrite))
            err_close_fds.extend((c2pread, c2pwrite))
        elif stdout == DEVNULL:
            c2pwrite = msvcrt.get_osfhandle(self._get_devnull())
        elif isinstance(stdout, int):
            c2pwrite = msvcrt.get_osfhandle(stdout)
        else:
            c2pwrite = msvcrt.get_osfhandle(stdout.fileno())
        c2pwrite = self._make_inheritable(c2pwrite)
        if stderr is None:
            errwrite = _winapi.GetStdHandle(_winapi.STD_ERROR_HANDLE)
            if errwrite is None:
                (_, errwrite) = _winapi.CreatePipe(None, 0)
                errwrite = Handle(errwrite)
                err_close_fds.append(errwrite)
                _winapi.CloseHandle(_)
        elif stderr == PIPE:
            (errread, errwrite) = _winapi.CreatePipe(None, 0)
            (errread, errwrite) = (Handle(errread), Handle(errwrite))
            err_close_fds.extend((errread, errwrite))
        elif stderr == STDOUT:
            errwrite = c2pwrite
        elif stderr == DEVNULL:
            errwrite = msvcrt.get_osfhandle(self._get_devnull())
        elif isinstance(stderr, int):
            errwrite = msvcrt.get_osfhandle(stderr)
        else:
            errwrite = msvcrt.get_osfhandle(stderr.fileno())
        errwrite = self._make_inheritable(errwrite)
    return (p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite)

def _make_inheritable(self, handle):
    """Return a duplicate of handle, which is inheritable"""
    h = _winapi.DuplicateHandle(_winapi.GetCurrentProcess(), handle, _winapi.GetCurrentProcess(), 0, 1, _winapi.DUPLICATE_SAME_ACCESS)
    return Handle(h)

def _filter_handle_list(self, handle_list):
    """Filter out console handles that can't be used
            in lpAttributeList["handle_list"] and make sure the list
            isn't empty. This also removes duplicate handles."""
    return list({handle for handle in handle_list if handle & 3 != 3 or _winapi.GetFileType(handle) != _winapi.FILE_TYPE_CHAR})

def _execute_child(self, args, executable, preexec_fn, close_fds, pass_fds, cwd, env, startupinfo, creationflags, shell, p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite, unused_restore_signals, unused_gid, unused_gids, unused_uid, unused_umask, unused_start_new_session, unused_process_group):
    """Execute program (MS Windows version)"""
    assert not pass_fds, 'pass_fds not supported on Windows.'
    if isinstance(args, str):
        pass
    elif isinstance(args, bytes):
        if shell:
            raise TypeError('bytes args is not allowed on Windows')
        args = list2cmdline([args])
    elif isinstance(args, os.PathLike):
        if shell:
            raise TypeError('path-like args is not allowed when shell is true')
        args = list2cmdline([args])
    else:
        args = list2cmdline(args)
    if executable is not None:
        executable = os.fsdecode(executable)
    if startupinfo is None:
        startupinfo = STARTUPINFO()
    else:
        startupinfo = startupinfo.copy()
    use_std_handles = -1 not in (p2cread, c2pwrite, errwrite)
    if use_std_handles:
        startupinfo.dwFlags |= _winapi.STARTF_USESTDHANDLES
        startupinfo.hStdInput = p2cread
        startupinfo.hStdOutput = c2pwrite
        startupinfo.hStdError = errwrite
    attribute_list = startupinfo.lpAttributeList
    have_handle_list = bool(attribute_list and 'handle_list' in attribute_list and attribute_list['handle_list'])
    if have_handle_list or (use_std_handles and close_fds):
        if attribute_list is None:
            attribute_list = startupinfo.lpAttributeList = {}
        handle_list = attribute_list['handle_list'] = list(attribute_list.get('handle_list', []))
        if use_std_handles:
            handle_list += [int(p2cread), int(c2pwrite), int(errwrite)]
        handle_list[:] = self._filter_handle_list(handle_list)
        if handle_list:
            if not close_fds:
                warnings.warn("startupinfo.lpAttributeList['handle_list'] overriding close_fds", RuntimeWarning)
            close_fds = False
    if shell:
        startupinfo.dwFlags |= _winapi.STARTF_USESHOWWINDOW
        startupinfo.wShowWindow = _winapi.SW_HIDE
        if not executable:
            comspec = os.environ.get('ComSpec')
            if not comspec:
                system_root = os.environ.get('SystemRoot', '')
                comspec = os.path.join(system_root, 'System32', 'cmd.exe')
                if not os.path.isabs(comspec):
                    raise FileNotFoundError('shell not found: neither %ComSpec% nor %SystemRoot% is set')
            if os.path.isabs(comspec):
                executable = comspec
        else:
            comspec = executable
        args = '{} /c "{}"'.format(comspec, args)
    if cwd is not None:
        cwd = os.fsdecode(cwd)
    sys.audit('subprocess.Popen', executable, args, cwd, env)
    try:
        (hp, ht, pid, tid) = _winapi.CreateProcess(executable, args, None, None, int(not close_fds), creationflags, env, cwd, startupinfo)
    finally:
        self._close_pipe_fds(p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite)
    self._child_created = True
    self._handle = Handle(hp)
    self.pid = pid
    _winapi.CloseHandle(ht)

def _internal_poll(self, _deadstate=None, _WaitForSingleObject=_winapi.WaitForSingleObject, _WAIT_OBJECT_0=_winapi.WAIT_OBJECT_0, _GetExitCodeProcess=_winapi.GetExitCodeProcess):
    """Check if child process has terminated.  Returns returncode
            attribute.

            This method is called by __del__, so it can only refer to objects
            in its local scope.

            """
    if self.returncode is None:
        if _WaitForSingleObject(self._handle, 0) == _WAIT_OBJECT_0:
            self.returncode = _GetExitCodeProcess(self._handle)
    return self.returncode

def _wait(self, timeout):
    """Internal implementation of wait() on Windows."""
    if timeout is None:
        timeout_millis = _winapi.INFINITE
    elif timeout <= 0:
        timeout_millis = 0
    else:
        timeout_millis = int(timeout * 1000)
    if self.returncode is None:
        result = _winapi.WaitForSingleObject(self._handle, timeout_millis)
        if result == _winapi.WAIT_TIMEOUT:
            raise TimeoutExpired(self.args, timeout)
        self.returncode = _winapi.GetExitCodeProcess(self._handle)
    return self.returncode

def send_signal(self, sig):
    """Send a signal to the process."""
    if self.returncode is not None:
        return
    if sig == signal.SIGTERM:
        self.terminate()
    elif sig == signal.CTRL_C_EVENT:
        os.kill(self.pid, signal.CTRL_C_EVENT)
    elif sig == signal.CTRL_BREAK_EVENT:
        os.kill(self.pid, signal.CTRL_BREAK_EVENT)
    else:
        raise ValueError('Unsupported signal: {}'.format(sig))

def terminate(self):
    """Terminates the process."""
    if self.returncode is not None:
        return
    try:
        _winapi.TerminateProcess(self._handle, 1)
    except PermissionError:
        rc = _winapi.GetExitCodeProcess(self._handle)
        if rc == _winapi.STILL_ACTIVE:
            raise
        self.returncode = rc

def _get_handles(self, stdin, stdout, stderr):
    """Construct and return tuple with IO objects:
            p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite
            """
    (p2cread, p2cwrite) = (-1, -1)
    (c2pread, c2pwrite) = (-1, -1)
    (errread, errwrite) = (-1, -1)
    with self._on_error_fd_closer() as err_close_fds:
        if stdin is None:
            pass
        elif stdin == PIPE:
            (p2cread, p2cwrite) = os.pipe()
            err_close_fds.extend((p2cread, p2cwrite))
            if self.pipesize > 0 and hasattr(fcntl, 'F_SETPIPE_SZ'):
                fcntl.fcntl(p2cwrite, fcntl.F_SETPIPE_SZ, self.pipesize)
        elif stdin == DEVNULL:
            p2cread = self._get_devnull()
        elif isinstance(stdin, int):
            p2cread = stdin
        else:
            p2cread = stdin.fileno()
        if stdout is None:
            pass
        elif stdout == PIPE:
            (c2pread, c2pwrite) = os.pipe()
            err_close_fds.extend((c2pread, c2pwrite))
            if self.pipesize > 0 and hasattr(fcntl, 'F_SETPIPE_SZ'):
                fcntl.fcntl(c2pwrite, fcntl.F_SETPIPE_SZ, self.pipesize)
        elif stdout == DEVNULL:
            c2pwrite = self._get_devnull()
        elif isinstance(stdout, int):
            c2pwrite = stdout
        else:
            c2pwrite = stdout.fileno()
        if stderr is None:
            pass
        elif stderr == PIPE:
            (errread, errwrite) = os.pipe()
            err_close_fds.extend((errread, errwrite))
            if self.pipesize > 0 and hasattr(fcntl, 'F_SETPIPE_SZ'):
                fcntl.fcntl(errwrite, fcntl.F_SETPIPE_SZ, self.pipesize)
        elif stderr == STDOUT:
            if c2pwrite != -1:
                errwrite = c2pwrite
            else:
                errwrite = sys.__stdout__.fileno()
        elif stderr == DEVNULL:
            errwrite = self._get_devnull()
        elif isinstance(stderr, int):
            errwrite = stderr
        else:
            errwrite = stderr.fileno()
    return (p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite)

def _posix_spawn(self, args, executable, env, restore_signals, p2cread, p2cwrite, c2pread, c2pwrite, errread, errwrite):
    """Execute program using os.posix_spawn()."""
    if env is None:
        env = os.environ
    kwargs = {}
    if restore_signals:
        sigset = []
        for signame in ('SIGPIPE', 'SIGXFZ', 'SIGXFSZ'):
            signum = getattr(signal, signame, None)
            if signum is not None:
                sigset.append(signum)
        kwargs['setsigdef'] = sigset
    file_actions = []
    for fd in (p2cwrite, c2pread, errread):
        if fd != -1:
            file_actions.append((os.POSIX_SPAWN_CLOSE, fd))
    for (fd, fd2) in ((p2cread, 0), (c2pwrite, 1), (errwrite, 2)):
        if fd != -1:
            file_actions.append((os.POSIX_SPAWN_DUP2, fd, fd2))
    if file_actions:
        kwargs['file_actions'] = file_actions
